package infra;

import domain.FxQuote;

import java.io.IOException;
import java.io.InputStream;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** Thin wrapper around the vendor quote CLI. One process per call. */
public class FxqClient {
    private final Path bin;
    private final long timeoutSeconds;

    public FxqClient(Path bin, long timeoutSeconds) {
        this.bin = bin;
        this.timeoutSeconds = timeoutSeconds;
    }

    /** Raw stdout line for {@code fxq rate PAIR DATE}. */
    public String rate(String pair, LocalDate date) {
        return rate(pair, date, false);
    }

    /** Raw stdout line for {@code fxq rate PAIR DATE --src 3} (settlement source). */
    public String settlementQuote(String pair, LocalDate date) {
        return rate(pair, date, true);
    }

    private String rate(String pair, LocalDate date, boolean settlementSource) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.add("rate");
        cmd.add(pair);
        cmd.add(date.toString());
        if (settlementSource) {
            cmd.add("--src");
            cmd.add("3");
        }
        return run(cmd);
    }

    /** Parses one quote line: {@code PAIR YYYY-MM-DD RATE [~N]}. */
    public static FxQuote parse(String line) {
        String[] t = line.trim().split("\\s+");
        if (t.length < 3) {
            throw new IllegalArgumentException("unexpected quote line: " + line);
        }
        boolean lagged = t.length > 3 && t[3].startsWith("~");
        return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), lagged);
    }

    private String run(List<String> cmd) {
        try {
            Process p = new ProcessBuilder(cmd).start();
            byte[] out;
            byte[] err;
            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
                out = o.readAllBytes();
                err = e.readAllBytes();
            }
            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new FxqException("timeout", cmd);
            }
            if (p.exitValue() != 0) {
                throw new FxqException(new String(err, StandardCharsets.UTF_8).trim(), cmd);
            }
            String line = new String(out, StandardCharsets.UTF_8).trim();
            if (line.isEmpty()) throw new FxqException("empty output", cmd);
            return line;
        } catch (IOException e) {
            throw new FxqException("exec failed: " + e.getMessage(), cmd);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new FxqException("interrupted", cmd);
        }
    }

    public static class FxqException extends RuntimeException {
        public FxqException(String code, List<String> cmd) {
            super("fxq failed [" + code + "]: " + String.join(" ", cmd));
        }
    }
}
package infra;

import domain.Partner;
import domain.StatementRow;
import domain.Transaction;
import util.Csv;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * CSV files in the data dir:
 *   transactions.csv       acquirer feed (approved_at in UTC)
 *   partners.csv           partner master
 *   partner-statement.csv  statements sent by partners (gross KRW per KST date)
 */
public class DataFiles {
    private final Path dir;
    private Map<String, Partner> partners;

    public DataFiles(Path dir) {
        this.dir = dir;
    }

    public List<Transaction> transactions() {
        List<Transaction> out = new ArrayList<>();
        for (List<String> c : rows("transactions.csv")) {
            out.add(new Transaction(c.get(0), c.get(1), Instant.parse(c.get(2)), c.get(3),
                    new BigDecimal(c.get(4)), Transaction.Type.valueOf(c.get(5))));
        }
        return out;
    }

    public Optional<Partner> partner(String id) {
        if (partners == null) {
            partners = new LinkedHashMap<>();
            for (List<String> c : rows("partners.csv")) {
                partners.put(c.get(0), new Partner(c.get(0), c.get(1), Integer.parseInt(c.get(2)), "Y".equals(c.get(3))));
            }
        }
        return Optional.ofNullable(partners.get(id));
    }

    public List<StatementRow> statements(LocalDate from, LocalDate to) {
        List<StatementRow> out = new ArrayList<>();
        for (List<String> c : rows("partner-statement.csv")) {
            LocalDate d = LocalDate.parse(c.get(0));
            if (d.isBefore(from) || d.isAfter(to)) continue;
            out.add(new StatementRow(d, c.get(1), Integer.parseInt(c.get(2)), Long.parseLong(c.get(3))));
        }
        return out;
    }

    /** Data rows (header and comment lines skipped), cells trimmed. */
    private List<List<String>> rows(String name) {
        List<String> lines;
        try {
            lines = Files.readAllLines(dir.resolve(name), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        List<List<String>> out = new ArrayList<>();
        boolean header = true;
        for (String line : lines) {
            if (!Csv.isDataLine(line)) continue;
            if (header) { header = false; continue; }
            out.add(Csv.split(line).stream().map(String::trim).toList());
        }
        return out;
    }
}
package util;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** KRW arithmetic shared by settlement and reporting. */
public final class Money {
    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);

    private Money() {}

    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
        return amount.multiply(rate)
                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    /** Commission on gross KRW; partner contract truncates fractional won. */
    public static long fee(long grossKrw, int feeBps) {
        if (grossKrw <= 0 || feeBps <= 0) return 0;
        return BigDecimal.valueOf(grossKrw)
                .multiply(BigDecimal.valueOf(feeBps))
                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
                .longValueExact();
    }

    public static String won(long krw) {
        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(krw);
    }

    public static String rate(BigDecimal rate) {
        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(rate);
    }
}
package util;

import java.util.ArrayList;
import java.util.List;

/** Minimal CSV line splitter (comma separated, double-quote escaping). */
public final class Csv {
    private Csv() {}

    public static List<String> split(String line) {
        List<String> out = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        boolean quoted = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (quoted) {
                if (c == '"' && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                    cur.append('"');
                    i++;
                } else if (c == '"') {
                    quoted = false;
                } else {
                    cur.append(c);
                }
            } else if (c == '"') {
                quoted = true;
            } else if (c == ',') {
                out.add(cur.toString());
                cur.setLength(0);
            } else {
                cur.append(c);
            }
        }
        out.add(cur.toString());
        return out;
    }

    public static boolean isDataLine(String line) {
        String t = line.trim();
        return !t.isEmpty() && !t.startsWith("#");
    }
}
package service;

import domain.DailyLine;
import domain.StatementRow;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Compares our daily lines with the partners' statements. */
public class ReconcileService {

    /** Difference between our settlement and the partner's statement for a date/partner. */
    public record Mismatch(LocalDate date, String partnerId, String field, long ours, long theirs) {
        public long diff() { return ours - theirs; }
    }

    public List<Mismatch> compare(List<DailyLine> ours, List<StatementRow> theirs) {
        Map<String, DailyLine> mine = new HashMap<>();
        for (DailyLine l : ours) mine.put(key(l.date(), l.partnerId()), l);
        List<Mismatch> out = new ArrayList<>();
        for (StatementRow r : theirs) {
            DailyLine l = mine.remove(key(r.date(), r.partnerId()));
            if (l == null) {
                out.add(new Mismatch(r.date(), r.partnerId(), "missing", 0, r.grossKrw()));
                continue;
            }
            if (l.count() != r.count()) out.add(new Mismatch(r.date(), r.partnerId(), "count", l.count(), r.count()));
            if (l.grossKrw() != r.grossKrw()) out.add(new Mismatch(r.date(), r.partnerId(), "gross", l.grossKrw(), r.grossKrw()));
        }
        for (DailyLine l : mine.values()) {
            out.add(new Mismatch(l.date(), l.partnerId(), "unexpected", l.grossKrw(), 0));
        }
        out.sort((a, b) -> a.date().equals(b.date()) ? a.partnerId().compareTo(b.partnerId()) : a.date().compareTo(b.date()));
        return out;
    }

    private static String key(LocalDate d, String partner) {
        return d + "|" + partner;
    }
}
package service;

import domain.FxQuote;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** Customer-facing exchange rate board for the app's travel wallet screen. */
public class RateBoardService {
    private final RateService rates;
    private final List<String> currencies;

    public RateBoardService(RateService rates, List<String> currencies) {
        this.rates = rates;
        this.currencies = currencies;
    }

    public List<FxQuote> board(LocalDate date) {
        List<FxQuote> out = new ArrayList<>();
        for (String c : currencies) {
            if (CurrencyPairs.supported(c)) out.add(rates.quote(c, date));
        }
        return out;
    }
}
package config;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.ZoneId;
import java.util.Arrays;
import java.util.List;
import java.util.Properties;

/** Loads conf/app.properties; system properties and SETTLE_* environment variables override. */
public final class AppConfig {
    private final Properties props = new Properties();

    private AppConfig() {}

    public static AppConfig load() {
        return load(Path.of("conf", "app.properties"));
    }

    public static AppConfig load(Path file) {
        AppConfig cfg = new AppConfig();
        try (InputStream in = Files.newInputStream(file)) {
            cfg.props.load(in);
        } catch (IOException e) {
            throw new IllegalStateException("cannot read config " + file, e);
        }
        return cfg;
    }

    public String get(String key) {
        String sys = System.getProperty("settle." + key);
        if (sys != null && !sys.isBlank()) return sys.trim();
        String env = System.getenv("SETTLE_" + key.toUpperCase().replace('.', '_'));
        if (env != null && !env.isBlank()) return env.trim();
        String v = props.getProperty(key);
        if (v == null) throw new IllegalStateException("missing config key " + key);
        return v.trim();
    }

    public Path fxqBin() { return Path.of(get("fxq.bin")); }

    public long fxqTimeoutSeconds() { return Long.parseLong(get("fxq.timeoutSeconds")); }

    public Path dataDir() { return Path.of(get("data.dir")); }

    public ZoneId businessZone() { return ZoneId.of(get("business.zone")); }

    public List<String> boardCurrencies() {
        return Arrays.stream(get("board.currencies").split(",")).map(String::trim).filter(s -> !s.isEmpty()).toList();
    }
}
