import domain.DailyLine;
import domain.FxQuote;
import domain.SettledTransaction;
import service.ReconcileService.Mismatch;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.List;
import java.util.Locale;

/** Text renderings for the ops console. */
public final class ReportFormatter {
    /** Shown instead of the rate on holiday lines (vendor B-2 value; must not leave the company). */
    static final String HOLIDAY_RATE_NOTE = "휴장일·정산 기준 환율 적용";

    private ReportFormatter() {}

    /**
     * Partner statement for sending to the partner. Rates of restricted (B-2) lines are replaced by a note;
     * the KRW amount is the settlement result and is shown as is.
     */
    public static String partnerDetail(String partnerId, String name, LocalDate from, LocalDate to,
                                       List<SettledTransaction> lines) {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("%s %s  %s ~ %s (정산일 KST)%n", partnerId, name, from, to));
        sb.append(String.format("%-10s  %-7s  %-3s  %14s  %-20s  %12s%n",
                "정산일", "거래번호", "통화", "외화금액", "적용환율", "원화금액"));
        long gross = 0;
        for (SettledTransaction s : lines) {
            String rate = s.rate().restricted() ? HOLIDAY_RATE_NOTE : Money.rate(s.rate().rate()) + unitNote(s.currency());
            sb.append(String.format("%-10s  %-7s  %-3s  %14s  %-20s  %12s%n",
                    s.date(), s.txnId(), s.currency(), foreign(s), rate, Money.won(s.krw())));
            gross += s.krw();
        }
        sb.append(String.format("합계 %d건 %s%n", lines.size(), Money.won(gross)));
        return sb.toString();
    }

    private static String unitNote(String currency) {
        return "JPY".equals(currency) ? " (100엔당)" : "";
    }

    private static String foreign(SettledTransaction s) {
        String pattern = "JPY".equals(s.currency()) ? "%,.0f" : "%,.2f";
        return String.format(Locale.ROOT, pattern, s.amount());
    }

